Handle background fetch failures gracefully.

**Implementation:**
```javascript
async function fetchAndCacheIcons(teamIconUrl) {
    try {
        const response = await chrome.runtime.sendMessage({
            action: "fetchIcon",
            url: teamIconUrl
        });

        if (!response.success) {
            throw new Error(response.error);
        }

        iconCache.teamIconDataUrl = response.dataUrl;
        iconCache.normalFavicon = await composeFavicon(response.dataUrl, false);
        iconCache.unreadFavicon = await composeFavicon(response.dataUrl, true);
    } catch (err) {
        i("Error fetching icon, using direct URL:", err.message);
        // Fall back to direct URL (may fail on toDataURL but shows icon)
        iconCache.teamIconDataUrl = teamIconUrl;
        iconCache.normalFavicon = null;
        iconCache.unreadFavicon = null;
    }
}
```

**File:** js/content.js

**Verify:** Block network request to icon URL, confirm extension doesn't crash and shows some favicon.

Handle timing issues when .c-team_icon loads after page ready.

**Implementation:**
```javascript
async function waitForTeamIcon(maxRetries = 5, delayMs = 500) {
    for (let i = 0; i < maxRetries; i++) {
        const iconUrl = h();
        if (iconUrl) return iconUrl;
        await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;
}

// In init function:
const teamIconUrl = await waitForTeamIcon();
if (!teamIconUrl) {
    i("Team icon not found after retries, using default behavior");
    return;
}
```

